    requires |l| > 0 // The list must not be empty
    ensures result == MaxElement(l) // The result is the maximum element of the list

// Helper function to find the maximum element in the sequence
function MaxElement(l: seq<int>) : int
    requires |l| > 0
    ensures forall i, j: int :: 0 <= i < |l| && 0 <= j < |l| ==> l[i] <= l[j] ==> result == l[j]
{
    if |l| == 1 then
        return l[0];
    else
        var maxRest := MaxElement(l[1..]);
        if l[0] > maxRest then
            return l[0];
        else
            return maxRest;
}
